import React, { useState, useEffect } from "react";
import {
  Rating,
  CircularProgress,
  Box,
  Typography,
  Card,
  CardContent,
  Avatar,
  Dialog,
  IconButton,
  Chip,
  Button
} from "@mui/material";
import Masonry from "@mui/lab/Masonry";
import UserAvatar from "../Components/UserAvatar";
import { Close, NavigateBefore, NavigateNext } from "@mui/icons-material";

const Testimonial = () => {
  const [testimonials, setTestimonials] = useState([]);
  const [displayTestimonials, setDisplayTestimonials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [imageDialogOpen, setImageDialogOpen] = useState(false);
  const [selectedImage, setSelectedImage] = useState(null);
  const [selectedTestimonial, setSelectedTestimonial] = useState(null);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [showAll, setShowAll] = useState(false);
  const [imageErrors, setImageErrors] = useState({}); // Track image errors
  const itemsPerPage = 15;

  const GOOGLE_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbxu79sYZb_yIEeM9pLZczPCAtw6AGCM0JpWYu2GuNWqyzTFh7FvwkmVG1SueS9JwC5lBA/exec";

  // Function to get thumbnail URL (small size for grid display)
  const getThumbnailUrl = (url) => {
    if (!url) return null;
    
    if (url.includes('googleusercontent.com')) {
      // Convert Google Photos-style URL to thumbnail
      return url.replace(/=s\d+(-c)?/, '=s150-c'); // 150px thumbnail
    }
    
    if (url.includes('drive.google.com/file/d/')) {
      const fileId = url.match(/\/file\/d\/([^\/]+)/)?.[1];
      if (fileId) {
        return `https://lh3.googleusercontent.com/d/${fileId}=s150-c`;
      }
    }
    
    return url;
  };

  // Function to get preview URL (full size for dialog)
  const getPreviewUrl = (url) => {
    if (!url) return null;
    
    if (url.includes('googleusercontent.com')) {
      // For Google Photos-style URLs, use larger size for preview
      return url.replace(/=s\d+(-c)?/, '=s800-c'); // 800px for preview
    }
    
    if (url.includes('drive.google.com/file/d/')) {
      const fileId = url.match(/\/file\/d\/([^\/]+)/)?.[1];
      if (fileId) {
        return `https://lh3.googleusercontent.com/d/${fileId}=s800-c`;
      }
    }
    
    return url;
  };

  // Function to parse additional photos
  const parseAdditionalPhotos = (photosData) => {
    if (!photosData || photosData === "No additional photos" || photosData === "Error storing photo") {
      return [];
    }
    
    try {
      let urlsArray = [];
      
      if (Array.isArray(photosData)) {
        urlsArray = photosData;
      } else if (typeof photosData === 'string') {
        urlsArray = photosData.split(',')
          .map(url => url.trim())
          .filter(url => url && url !== "Error storing photo" && url !== "No additional photos");
      } else {
        urlsArray = [photosData];
      }
      
      return urlsArray.filter(url => url);
      
    } catch (error) {
      console.error("Error parsing additional photos:", error);
      return [];
    }
  };

  // Track image errors
  const handleImageError = (testimonialIndex, photoIndex, url) => {
    console.error("Image failed to load:", url);
    setImageErrors(prev => ({
      ...prev,
      [`${testimonialIndex}-${photoIndex}`]: true
    }));
  };

  const fetchTestimonials = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const response = await fetch(`${GOOGLE_SCRIPT_URL}?action=getTestimonials`);
      if (!response.ok) throw new Error(`Failed to fetch testimonials: ${response.status}`);
      
      const data = await response.json();
      
      if (data.success && data.testimonials) {
        const processedTestimonials = data.testimonials.map((testimonial, index) => {
          const additionalPhotos = parseAdditionalPhotos(testimonial.additionalPhotos);
          const profilePhoto = testimonial.photo && testimonial.photo !== "No photo" 
            ? getThumbnailUrl(testimonial.photo)
            : null;
          
          return {
            ...testimonial,
            additionalPhotos: additionalPhotos,
            photo: profilePhoto,
            originalPhoto: testimonial.photo || null,
            originalAdditionalPhotos: additionalPhotos || []
          };
        });
        
        setTestimonials(processedTestimonials);
        setDisplayTestimonials(processedTestimonials.slice(0, itemsPerPage));
      } else {
        throw new Error(data.message || "No testimonials found");
      }
    } catch (err) {
      console.error("Fetch error:", err);
      setError(err.message);
      setTestimonials([]);
      setDisplayTestimonials([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTestimonials();
  }, []);

  useEffect(() => {
    if (showAll) {
      setDisplayTestimonials(testimonials);
    } else {
      setDisplayTestimonials(testimonials.slice(0, itemsPerPage));
    }
  }, [showAll, testimonials]);

  const handleImageClick = (testimonial, imageUrl, index = 0, isThumbnail = true) => {
    const originalPhoto = testimonial.originalPhoto || testimonial.photo;
    const originalAdditionalPhotos = testimonial.originalAdditionalPhotos || testimonial.additionalPhotos || [];
    
    let previewUrl;
    if (isThumbnail) {
      let originalUrl;
      if (index === 0) {
        originalUrl = originalPhoto;
      } else {
        const photoIndex = index - 1;
        originalUrl = originalAdditionalPhotos[photoIndex] || imageUrl;
      }
      previewUrl = getPreviewUrl(originalUrl);
    } else {
      previewUrl = getPreviewUrl(imageUrl);
    }
    
    setSelectedTestimonial(testimonial);
    setSelectedImage(previewUrl);
    setCurrentImageIndex(index);
    setImageDialogOpen(true);
  };

  const handleCloseDialog = () => {
    setImageDialogOpen(false);
    setSelectedImage(null);
    setSelectedTestimonial(null);
    setCurrentImageIndex(0);
  };

  const handleNextImage = () => {
    if (selectedTestimonial) {
      const profilePhoto = selectedTestimonial.originalPhoto || selectedTestimonial.photo;
      const additionalPhotos = selectedTestimonial.originalAdditionalPhotos || selectedTestimonial.additionalPhotos || [];
      
      const allImages = [
        ...(profilePhoto && profilePhoto !== "No photo" ? [profilePhoto] : []),
        ...additionalPhotos.filter(img => img && img !== "No photo")
      ];
      
      if (allImages.length === 0) return;
      
      const nextIndex = (currentImageIndex + 1) % allImages.length;
      setCurrentImageIndex(nextIndex);
      setSelectedImage(getPreviewUrl(allImages[nextIndex]));
    }
  };

  const handlePrevImage = () => {
    if (selectedTestimonial) {
      const profilePhoto = selectedTestimonial.originalPhoto || selectedTestimonial.photo;
      const additionalPhotos = selectedTestimonial.originalAdditionalPhotos || selectedTestimonial.additionalPhotos || [];
      
      const allImages = [
        ...(profilePhoto && profilePhoto !== "No photo" ? [profilePhoto] : []),
        ...additionalPhotos.filter(img => img && img !== "No photo")
      ];
      
      if (allImages.length === 0) return;
      
      const prevIndex = (currentImageIndex - 1 + allImages.length) % allImages.length;
      setCurrentImageIndex(prevIndex);
      setSelectedImage(getPreviewUrl(allImages[prevIndex]));
    }
  };

  const toggleShowAll = () => {
    setShowAll(!showAll);
  };

  const testImageUrl = (url) => {
    if (!url) return false;
    return url.includes('drive.google.com') || url.includes('googleusercontent.com');
  };

  if (loading) {
    return (
      <Box sx={{ display: "flex", justifyContent: "center", alignItems: "center", minHeight: 400, background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)", color: "white" }}>
        <Box sx={{ textAlign: "center" }}>
          <CircularProgress sx={{ color: "#FF9800", mb: 2 }} />
          <Typography variant="h6">Loading testimonials...</Typography>
        </Box>
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ textAlign: "center", minHeight: 400, background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)", color: "white", padding: 4 }}>
        <Typography variant="h4" color="error" gutterBottom>Error Loading Testimonials</Typography>
        <Typography variant="body1">{error}</Typography>
        <Button 
          onClick={fetchTestimonials} 
          variant="contained" 
          sx={{ background: "#FF9800", mt: 2 }}
        >
          Try Again
        </Button>
      </Box>
    );
  }

  return (
    <Box
      id="testimonials"
      sx={{
        background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        color: "white",
        p: { xs: 3, md: 6 },
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        textAlign: "center"
      }}
    >
      <Typography
        variant="h4"
        component="h4"
        sx={{
          mb: 5,
          fontFamily: "'AlanSans', sans-serif",
          fontWeight: 700,
          background: "linear-gradient(45deg, #FF9800 30%, #FF5722 90%)",
          backgroundClip: "text",
          WebkitBackgroundClip: "text",
          color: "transparent"
        }}
      >
        What They've Said
      </Typography>

      <Box sx={{ width: "100%", maxWidth: 1200, justifyContent: "center" }}>
        <Masonry columns={{ xs: 1, sm: 2, md: 3 }} spacing={3}>
          {displayTestimonials.map((testimonial, testimonialIndex) => {
            const additionalPhotos = testimonial.additionalPhotos || [];
            const hasAdditionalPhotos = additionalPhotos.length > 0;

            return (
              <Card
                key={testimonialIndex}
                sx={{
                  background: "rgba(255,255,255,0.05)",
                  backdropFilter: "blur(10px)",
                  border: "1px solid rgba(255,255,255,0.1)",
                  borderRadius: 2,
                  overflow: "hidden",
                  transition: "transform 0.3s ease, box-shadow 0.3s ease",
                  "&:hover": {
                    transform: "translateY(-5px)",
                  }
                }}
              >
                <CardContent sx={{ p: 2, display: "flex", flexDirection: "column", textAlign: "left" }}>
                  <Box sx={{ display: "flex", alignItems: "center", mb: 1 }}>
                    <UserAvatar photoUrl={testimonial.photo} name={testimonial.name} />
                    
                    <Box sx={{ ml: 2 }}>
                      <Typography variant="subtitle1" sx={{ color: "#FFFF", fontWeight: 600, fontFamily: "'AlanSans', sans-serif" }}>
                        {testimonial.name}
                      </Typography>
                      <Rating
                        value={testimonial.rating}
                        readOnly
                        size="small"
                        sx={{ color: "#FF9800", "& .MuiRating-iconFilled": { color: "#FF9800" } }}
                      />
                      <Typography variant="caption" sx={{ color: "rgba(255,255,255,0.5)", display: "block", mt: 0.5 }}>
                        {new Date(testimonial.timestamp).toLocaleDateString()}
                      </Typography>
                    </Box>
                  </Box>

                  <div className="relative text-[rgba(255,255,255,0.9)] font-in px-2 text-center flex justify-center mb-2">
                    <div className="absolute text-[#FF9800] text-2xl top-0 left-0">"</div>
                    <div className="absolute text-[#FF9800] text-2xl bottom-0 right-0">"</div>
                    {testimonial.comment} 
                  </div>

                  {/* Additional Photos Masonry */}
                  {hasAdditionalPhotos && (
                    <Box sx={{ mt: 2 }}>
                      <Typography variant="caption" sx={{ color: "rgba(255,255,255,0.7)", mb: 1, display: "block" }}>
                        Additional Photos ({additionalPhotos.length}):
                      </Typography>
                      <Box sx={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 1 }}>
                        {additionalPhotos.map((photoUrl, photoIndex) => {
                          const isValidUrl = testImageUrl(photoUrl);
                          const thumbnailUrl = getThumbnailUrl(photoUrl);
                          const imageKey = `${testimonialIndex}-${photoIndex}`;
                          const hasError = imageErrors[imageKey];

                          return (
                            <Box
                              key={photoIndex}
                              onClick={() => handleImageClick(testimonial, thumbnailUrl, photoIndex + 1, true)}
                              sx={{
                                cursor: isValidUrl && !hasError ? "pointer" : "default",
                                borderRadius: 1,
                                overflow: "hidden",
                                transition: "transform 0.2s ease",
                                "&:hover": {
                                  transform: isValidUrl && !hasError ? "scale(1.05)" : "none"
                                },
                                aspectRatio: "1",
                                backgroundColor: hasError ? "rgba(255,0,0,0.3)" : "rgba(255,255,255,0.1)",
                                border: hasError ? "1px solid rgba(255,0,0,0.5)" : "1px solid rgba(255,255,255,0.2)",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                position: "relative"
                              }}
                            >
                              {isValidUrl && !hasError ? (
                                <img
                                  src={thumbnailUrl}
                                  alt={`Additional photo ${photoIndex + 1} by ${testimonial.name}`}
                                  style={{
                                    width: "100%",
                                    height: "100%",
                                    objectFit: "cover",
                                    display: "block",
                                  }}
                                  onError={() => handleImageError(testimonialIndex, photoIndex, thumbnailUrl)}
                                  onLoad={() => console.log("Thumbnail loaded successfully:", thumbnailUrl)}
                                />
                              ) : (
                                <Box sx={{ color: "white", fontSize: "10px", textAlign: "center", padding: "4px" }}>
                                  {hasError ? "❌ Load Failed" : "⚠️ Invalid URL"}
                                  <br />
                                  <small>{photoUrl?.substring(0, 20)}...</small>
                                </Box>
                              )}
                            </Box>
                          );
                        })}
                      </Box>
                    </Box>
                  )}
                </CardContent>
              </Card>
            );
          })}
        </Masonry>

        {/* View More/Less Button */}
        {testimonials.length > itemsPerPage && (
          <Box sx={{ display: "flex", justifyContent: "center", mt: 4 }}>
            <Button
              onClick={toggleShowAll}
              variant="outlined"
              sx={{
                color: "#FF9800",
                borderColor: "#FF9800",
                "&:hover": {
                  borderColor: "#FF5722",
                  backgroundColor: "rgba(255,152,0,0.1)"
                }
              }}
            >
              {showAll ? "View Less" : `View More (${testimonials.length - itemsPerPage} more)`}
            </Button>
          </Box>
        )}
      </Box>

      {/* Image Dialog - Full size preview */}
      <Dialog
        open={imageDialogOpen}
        onClose={handleCloseDialog}
        maxWidth="lg"
        fullWidth
        sx={{
          "& .MuiDialog-paper": {
            background: "rgba(0,0,0,0.9)",
            color: "white",
            userSelect: "text",
            WebkitUserSelect: "text",
            MozUserSelect: "text",
          }
        }}
      >
        {selectedImage && selectedTestimonial && (
          <>
            <IconButton
              onClick={handleCloseDialog}
              sx={{
                position: "absolute",
                right: 8,
                top: 8,
                color: "white",
                background: "rgba(0,0,0,0.5)",
                "&:hover": {
                  background: "rgba(255,0,0,0.5)"
                },
                zIndex: 1000
              }}
            >
              <Close />
            </IconButton>

            <IconButton
              onClick={handlePrevImage}
              sx={{
                position: "absolute",
                left: 8,
                top: "50%",
                transform: "translateY(-50%)",
                color: "white",
                background: "rgba(0,0,0,0.5)",
                "&:hover": {
                  background: "rgba(255,152,0,0.5)"
                },
                zIndex: 1000
              }}
            >
              <NavigateBefore />
            </IconButton>

            <IconButton
              onClick={handleNextImage}
              sx={{
                position: "absolute",
                right: 8,
                top: "50%",
                transform: "translateY(-50%)",
                color: "white",
                background: "rgba(0,0,0,0.5)",
                "&:hover": {
                  background: "rgba(255,152,0,0.5)"
                },
                zIndex: 1000
              }}
            >
              <NavigateNext />
            </IconButton>

            <Box sx={{ 
              display: "flex", 
              justifyContent: "center", 
              alignItems: "center", 
              p: 2, 
              minHeight: "400px",
              backgroundColor: "rgba(255,255,255,0.1)",
              "& img": {
                WebkitTouchCallout: "default",
                WebkitUserSelect: "auto",
                KhtmlUserSelect: "auto",
                MozUserSelect: "auto",
                msUserSelect: "auto",
                userSelect: "auto",
                pointerEvents: "auto",
                maxWidth: "100%",
                maxHeight: "70vh",
                objectFit: "contain",
              }
            }}>
              <img
                src={selectedImage}
                alt="Enlarged view"
                style={{
                  maxWidth: "100%",
                  maxHeight: "70vh",
                  objectFit: "contain",
                }}
                onError={(e) => {
                  console.error("Preview image failed to load:", selectedImage);
                  e.target.style.display = 'none';
                }}
                onContextMenu={(e) => e.preventDefault()}
              />
            </Box>

            <Box sx={{ p: 2, borderTop: "1px solid rgba(255,255,255,0.1)" }}>
              <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                <Box>
                  <Typography variant="h6" sx={{ color: "white", fontFamily: "'AlanSans', sans-serif" }}>
                    {selectedTestimonial.name}
                  </Typography>
                  <Rating
                    value={selectedTestimonial.rating}
                    readOnly
                    size="small"
                    sx={{ color: "#FF9800" }}
                  />
                </Box>
                <Chip
                  label={`${currentImageIndex + 1} / ${[
                    ...(selectedTestimonial.originalPhoto && selectedTestimonial.originalPhoto !== "No photo" ? [selectedTestimonial.originalPhoto] : []),
                    ...((selectedTestimonial.originalAdditionalPhotos || selectedTestimonial.additionalPhotos || []).filter(img => img && img !== "No photo"))
                  ].length}`}
                  sx={{ color: "white", background: "rgba(255,152,0,0.3)" }}
                />
              </Box>
              <Typography variant="body2" sx={{ color: "rgba(255,255,255,0.8)", mt: 1 }}>
                {selectedTestimonial.comment}
              </Typography>
            </Box>
          </>
        )}
      </Dialog>

      {testimonials.length === 0 && !loading && (
        <Box sx={{ textAlign: "center", mt: 4 }}>
          <Typography variant="h6" sx={{ color: "rgba(255,255,255,0.7)" }}>
            No testimonials yet. Be the first to share your experience!
          </Typography>
        </Box>
      )}
    </Box>
  );
};

export default Testimonial;
